import pathlib,stat,json,urllib.request,urllib.error
base=pathlib.Path('/home/appontrack/public_html')
paths=['.htaccess','saas/.htaccess','saas/console/.htaccess','saas/console/index.php','saas/console/assets/css/app.css','saas/mobile/updates/latest.json']
fs=[]
for p in paths:
 obj=base/p
 info={'path':p,'exists':obj.exists(),'symlink':obj.is_symlink()}
 if obj.exists():
  info['mode']=oct(stat.S_IMODE(obj.stat().st_mode));info['size']=obj.stat().st_size
  if p.endswith('.htaccess'):info['rules']=obj.read_text(errors='replace')[:2200]
 fs.append(info)
urls=[]
for path in ['/saas/console/index.php','/saas/console/','/saas/console/README.md','/saas/console/assets/js/app.js','/saas/mobile/updates/latest.json']:
 try:
  with urllib.request.urlopen(urllib.request.Request('https://app.ontrackegy.com'+path,headers={'User-Agent':'OnTrack-Route-Probe'}),timeout=5) as x:urls.append([path,x.status,x.geturl(),x.headers.get('Content-Type','')])
 except urllib.error.HTTPError as e:urls.append([path,e.code,e.geturl()])
 except Exception as e:urls.append([path,type(e).__name__])
print(json.dumps({'fs':fs,'urls':urls}))
